import{_ as i,c as n,o as a,ag as t}from"./chunks/framework.B3RpK1bM.js";const p=JSON.parse('{"title":"Definition","description":"","frontmatter":{},"headers":[],"relativePath":"en_EN/definition.md","filePath":"en_EN/definition.md","lastUpdated":1769658044000}'),o={name:"en_EN/definition.md"};function s(l,e,r,c,d,u){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="definition" tabindex="-1">Definition <a class="header-anchor" href="#definition" aria-label="Permalink to &quot;Definition&quot;">​</a></h1><p><a href="./">Return to Table of Contents</a></p><p>To ensure that developers and users can describe the relationship between supply and demand in a standardized way, ensuring that communication processes do not generate misunderstandings, the following definitions have been provided for some important concepts. Generally speaking, we assume that developers and users understand these concepts.</p><h2 id="logical-definitions" tabindex="-1">Logical Definitions <a class="header-anchor" href="#logical-definitions" aria-label="Permalink to &quot;Logical Definitions&quot;">​</a></h2><ul><li>Visual Novel Game (NVG): A type of game where the main content is written text, with images used as auxiliary tools.</li><li>Text Adventure Game (TAD): An electronic game that uses text-based scripts to interact with players, combining graphics, music, and performances.</li><li>Galgame: A genre of games centered around interactions between anime characters.</li><li>Low Code Development: A development mode where a small amount of low-cost handwritten code is used to quickly develop applications.</li><li>Game Engine: A software framework used for game development, focusing on core dependencies in ezgal.</li></ul><h2 id="function-definitions" tabindex="-1">Function Definitions <a class="header-anchor" href="#function-definitions" aria-label="Permalink to &quot;Function Definitions&quot;">​</a></h2><ul><li>Full Screen Box (FSB): The FSB is a window specifically designed for visual novels (NVG), occupying most of the screen space and facilitating text descriptions.</li><li>Dialogue Box (Dialogue): The dialogue box is a window specifically designed for text adventures (TAD) and generally occupies the bottom part of the screen, primarily used to highlight character dialogues.</li></ul><h2 id="language-definitions" tabindex="-1">Language Definitions <a class="header-anchor" href="#language-definitions" aria-label="Permalink to &quot;Language Definitions&quot;">​</a></h2><ul><li>ezlang: ezlang (light language) is an interpreter used by ezgal to convert developer&#39;s script languages into customized JSON formats. Its core idea is to achieve low learning costs through script-based low-code development.</li><li>Script: Scripts include both script and performance parts, which form the core concept of ezlang.</li><li>Script: One of the core concepts in ezlang is a script document that simulates a play-by-play format, including text, dialogues, and options.</li><li>Performance: The performance includes elements such as image control, sound effects, and special effects, serving as additional functions in ezlang.</li></ul>',9)])])}const h=i(o,[["render",s]]);export{p as __pageData,h as default};
